C(sdt, "public TreeSeedTask(@WLD@ w, String wn, java.util.UUID u, @PR@ pr, int x, int y, int z, int si, int r) { this.w = w; this.wn = wn; this.u = u; this.pr = pr; this.x = x; this.y = y; this.z = z; this.si = si; this.r = r; }")
F(sed, "public static final String[] SEED = %s;" % jstr(_SOW_SEEDIDS))                       # sorted seed bag item ids ...
F(sed, "public static final String[] CROP = %s;" % jstr([_s[1] for _s in SOW_SEEDS]))         # ... -> the crop block a hand plant places
F(sed, "public static final int[] SOILG = %s;" % jint([SOW_GROUPS.index(_s[2]) for _s in SOW_SEEDS]))   # ... -> its soil group
F(sed, "public static final String[] SOIL = %s;" % jstr(_SOW_SOILK))                       # sorted "<group>|<block item id>"
F(sed, "public static final int RMAX = 4;")          # the hard radius cap (9 x 9) whatever the Server Setup rows say
F(sed, "public static final int REFUSE_MAX = 4;")    # refused cells (protection) before an area plant stops
F(sed, "public static final java.util.concurrent.ConcurrentHashMap ACTIVE = new java.util.concurrent.ConcurrentHashMap();")   # UUID -> TRUE while our own plants run
F(sed, "public static volatile java.util.Map TEST_BLOCKS = null;")    # harness only: "x|y|z" -> block family id (no world)
F(sed, "public static volatile int[] TEST_HAND = null;")              # harness only: [seeds left in the hand stack]
F(sed, "public static volatile java.util.Set TEST_DENY = null;")      # harness only: "x|y|z" cells protection refuses
F(sed, "public static volatile java.util.List TEST_LOG = null;")      # harness only: "hand|pocket|refused x y z" per cell
F(sed, "public static volatile long RUNS = 0L;")
F(sed, "public static volatile long PLANTED = 0L;")
F(sed, "public static volatile long POCKET = 0L;")
F(sed, "public static volatile long REFUSED = 0L;")
F(sed, "public static volatile long MISSED = 0L;")
F(sed, "public static volatile long LOST = 0L;")
F(sed, "public static boolean FAILED_ONCE = false;")
M(sed, r"""
public static void failed(Throwable t) {
  if (!FAILED_ONCE) { FAILED_ONCE = true; @PKG@.TreeCfg.warn("Wide Sowing failed (logged once; that cell was skipped): " + t); }
}""")
M(sed, r"""
public static int seedIdx(String id) {
  if (id == null || !id.startsWith("Plant_Seeds_")) return -1;
  int i = java.util.Arrays.binarySearch(SEED, id);
  return i < 0 ? -1 : i;
}""")
M(sed, r"""
public static boolean soilOk(int si, String fam) {
  if (fam == null || fam.length() == 0 || si < 0 || si >= SOILG.length) return false;
  return java.util.Arrays.binarySearch(SOIL, SOILG[si] + "|" + fam) >= 0;
}""")
M(sed, r"""
public static boolean isAir(String fam) {
  return fam != null && (fam.length() == 0 || fam.equals("Empty"));
}""")
# the planting radius = the Wide Sowing row (TreeSk "sow": per x rank, at most .max), whole blocks, at most RMAX
M(sed, r"""
public static int radius(java.util.UUID u) {
  double d = @PKG@.TreeSk.sum(u, "sow");
  if (!(d > 0.0)) return 0;
  int r = (int) Math.floor(d + 1.0E-9);
  if (r > RMAX) r = RMAX;
  return r < 0 ? 0 : r;
}""")
M(sed, "public static String key(int x, int y, int z) { return x + \"|\" + y + \"|\" + z; }")
# the block at a cell as its FAMILY (the item id: tilled soil's watered / fertilized states and a crop's growth stages share it); "Empty" /
# "" = air; null = not loaded
M(sed, r"""
public static String famAt(@WLD@ w, int x, int y, int z) {
  java.util.Map tb = TEST_BLOCKS;
  if (tb != null) { Object o = tb.get(key(x, y, z)); return o == null ? "" : o.toString(); }
  if (w == null) return null;
  try {
    @CHS@ cs = w.getChunkStore();
    if (cs == null) return null;
    @REF@ sr = cs.getChunkSectionReferenceAtBlock(x, y, z);
    if (sr == null || !sr.isValid()) return null;
    @BSC@ sec = (@BSC@) cs.getStore().getComponent(sr, @BSC@.getComponentType());
    if (sec == null) return null;
    @BTY@ bt = (@BTY@) @BTY@.getAssetMap().getAsset(sec.get(x, y, z));
    if (bt == null) return "";
    String id = @PKG@.TreeDefs.bid(bt);
    if (isAir(id)) return id;
    String f = @PKG@.TreeDefs.family(bt);
    return f == null ? id : f;
  } catch (Throwable t) { return null; }
}""")
# a SkyySacks bridge call (sacks:fn:take / put / commit: Object[] { UUID, item id, Long n } -> Long; world thread only)
M(sed, r"""
public static long bag(String key, java.util.UUID u, String id, long n) {
  try {
    Object f = @PKG@.TreeStore.bridge().get(key);
    if (!(f instanceof java.util.function.Function)) return 0L;
    Object r = ((java.util.function.Function) f).apply(new Object[] { u, id, Long.valueOf(n) });
    long m = r instanceof Number ? ((Number) r).longValue() : 0L;
    return m < 0L ? 0L : m;
  } catch (Throwable t) { failed(t); return 0L; }
}""")
M(sed, r"""
public static void note(String what, int x, int y, int z) {
  java.util.List l = TEST_LOG;
  if (l != null) l.add(what + " " + x + " " + y + " " + z);
}""")
# the stack in hand still holds this seed bag (the hotbar's active slot - where the hand plant took its seed)
M(sed, r"""
public static boolean handHas(@PKG@.TreeSeedTask g) {
  int[] th = TEST_HAND;
  if (th != null) return th[0] > 0;
  if (g.pr == null) return false;
  @REF@ r = g.pr.getReference();
  if (r == null || !r.isValid()) return false;
  @ST@ st = r.getStore();
  @HOTB@ hb = (@HOTB@) st.getComponent(r, @HOTB@.getComponentType());
  if (hb == null) return false;
  @IS@ s = hb.getActiveItem();
  return s != null && !s.isEmpty() && s.getQuantity() > 0 && SEED[g.si].equals(s.getItemId());
}""")
# ONE cell through the engine's own hand-plant call (PlaceBlockInteraction's BlockPlaceUtils.placeBlock): a real PlaceBlockEvent on the
# player (protection / collection locks / placed marks), face Up, no rotation; hand = the engine takes 1 from the active hotbar slot
# (Adventure only, like a hand plant), else a fresh 1-seed stack that nothing takes (the Pocket Dimension paid it)
M(sed, r"""
public static boolean place(@PKG@.TreeSeedTask g, int x, int y, int z, boolean hand) {
  java.util.Map tb = TEST_BLOCKS;
  if (tb != null) {
    java.util.Set dn = TEST_DENY;
    if (dn != null && dn.contains(key(x, y, z))) return false;
    tb.put(key(x, y, z), CROP[g.si]);
    int[] th = TEST_HAND;
    if (hand && th != null) th[0] = th[0] - 1;
    return true;
  }
  if (g.pr == null || g.w == null) return false;
  @REF@ r = g.pr.getReference();
  if (r == null || !r.isValid()) return false;
  @ST@ st = r.getStore();
  if (!st.isInThread()) return false;
  @CHS@ cs = g.w.getChunkStore();
  if (cs == null) return false;
  @REF@ sr = cs.getChunkSectionReferenceAtBlock(x, y, z);
  if (sr == null || !sr.isValid()) return false;
  @HOTB@ hb = (@HOTB@) st.getComponent(r, @HOTB@.getComponentType());
  if (hb == null) return false;
  @ICT@ ic = hb.getInventory();
  if (ic == null) return false;
  byte slot = hb.getActiveSlot();
  @IS@ held = hand ? ic.getItemStack((short) slot) : new @IS@(SEED[g.si], 1);
  if (held == null || held.isEmpty() || !SEED[g.si].equals(held.getItemId())) return false;
  @PBROT@ rot = new @PBROT@(@PROT@.None, @PROT@.None, @PROT@.None);
  return @BPU@.placeBlock(r, held, CROP[g.si], ic, new @V3I@(0, 1, 0), new @V3I@(x, y, z), rot, slot, hand, sr, cs.getStore(), st, false, false, false);
}""")
# one cell: 1 = planted, 0 = refused (protection / the engine said no - a Pocket seed goes back), -1 = no seed left (hand and Pocket empty)
M(sed, r"""
public static int one(@PKG@.TreeSeedTask g, int x, int y, int z) {
  String seed = SEED[g.si];
  String crop = CROP[g.si];
  if (handHas(g)) {
    boolean ok = false;
    try { ok = place(g, x, y, z, true); } catch (Throwable t) { failed(t); }
    if (ok) { note("hand", x, y, z); return 1; }
    note("refused", x, y, z);
    return 0;
  }
  long got = bag("sacks:fn:take", g.u, seed, 1L);
  if (got < 1L) return -1;
  boolean ok2 = false;
  try { ok2 = place(g, x, y, z, false); } catch (Throwable t2) { failed(t2); }
  if (ok2 || crop.equals(famAt(g.w, x, y, z))) {
    bag("sacks:fn:commit", g.u, seed, 1L);
    POCKET = POCKET + 1L;
    note("pocket", x, y, z);
    return 1;
  }
  if (bag("sacks:fn:put", g.u, seed, 1L) < 1L) {
    LOST = LOST + 1L;
    @PKG@.TreeCfg.warn("Wide Sowing: 1 " + seed + " taken from the Pocket Dimension of " + g.u + " could not be put back (the plant at " + x + " " + y + " " + z + " was refused) - give it back by hand");
  }
  note("refused", x, y, z);
  return 0;
}""")
# THE AREA PLANT (world thread, the tick after the hand plant): the hand plant landed (the clicked cell holds the crop) -> rings 1..r around
# it at the same height, nearest first; a cell = air above the seed's own soil; stops when out of seeds or after REFUSE_MAX refusals
M(sed, r"""
public static int plant(@PKG@.TreeSeedTask g) {
  RUNS = RUNS + 1L;
  if (g == null || g.si < 0 || g.si >= SEED.length || g.r <= 0 || g.u == null) return 0;
  String crop = CROP[g.si];
  String c = famAt(g.w, g.x, g.y, g.z);
  if (c == null || !c.equals(crop)) { MISSED = MISSED + 1L; return 0; }
  if (TEST_BLOCKS == null) {
    if (g.pr == null) return 0;
    @REF@ pref = g.pr.getReference();
    if (pref == null || !pref.isValid() || !pref.getStore().isInThread()) return 0;
  }
  int n = 0;
  int ref = 0;
  boolean stop = false;
  int rr = g.r > RMAX ? RMAX : g.r;
  ACTIVE.put(g.u, Boolean.TRUE);
  try {
    for (int ring = 1; ring <= rr && !stop; ring++) {
      for (int dx = 0 - ring; dx <= ring && !stop; dx++) {
        for (int dz = 0 - ring; dz <= ring && !stop; dz++) {
          if (Math.abs(dx) != ring && Math.abs(dz) != ring) continue;
          int x = g.x + dx;
          int z = g.z + dz;
          String b = famAt(g.w, x, g.y - 1, z);
          if (!soilOk(g.si, b)) continue;
          if (!isAir(famAt(g.w, x, g.y, z))) continue;
          int res = one(g, x, g.y, z);
          if (res < 0) stop = true;
          else if (res == 0) { ref = ref + 1; REFUSED = REFUSED + 1L; if (ref >= REFUSE_MAX) stop = true; }
          else n = n + 1;
        }
      }
    }
  } finally {
    ACTIVE.remove(g.u);
  }
  if (n > 0) {
    PLANTED = PLANTED + (long) n;
    @PKG@.TreeMsg.add(g.u, "seeds sown (Wide Sowing)", (long) n);
  }
  return n;
}""")
M(sdt, r"""
public void run() {
  try { @PKG@.TreeSeed.plant(this); } catch (Throwable t) { @PKG@.TreeSeed.failed(t); }
}""")
# a hand plant of a seed bag (PlaceBlockEvent, not cancelled so far): 0 = nothing to do, 1 = queued on the world thread, 2 = ran now (harness)
M(sed, r"""
public static int onPlace0(java.util.UUID u, @PR@ pr, @WLD@ w, String wn, String id, int x, int y, int z) {
  if (u == null || ACTIVE.containsKey(u)) return 0;
  int si = seedIdx(id);
  if (si < 0) return 0;
  if (@PKG@.TreeStore.busy(u)) return 0;
  int r = radius(u);
  if (r <= 0) return 0;
  @PKG@.TreeSeedTask g = new @PKG@.TreeSeedTask(w, wn, u, pr, x, y, z, si, r);
  if (TEST_BLOCKS != null || w == null) { g.run(); return 2; }
  w.execute(g);
  return 1;
}""")
M(sed, r"""
public static String counts() {
  return "Wide Sowing: " + RUNS + " area plants, " + PLANTED + " extra seeds sown (" + POCKET + " from the Pocket Dimension), " + REFUSED + " cells refused, " + MISSED + " hand plants that did not land" + (LOST > 0L ? ", " + LOST + " Pocket seeds LOST" : "");
}""")
C(ssy, "public TreeSeedSys() { super(@PBE@.class); }")
F(ssy, "public static boolean FAILED_ONCE = false;")
M(ssy, r"""
public @QRY@ getQuery() {
  return com.hypixel.hytale.component.Archetype.empty();
}""")
M(ssy, r"""
public void handle(int idx, @ACH@ chunk, @ST@ st, @CB@ buf, @EV@ ev) {
  try {
    @PBE@ e = (@PBE@) ev;
    if (e.isCancelled()) return;
    @IS@ it = e.getItemInHand();
    if (it == null) return;
    String id = it.getItemId();
    if (@PKG@.TreeSeed.seedIdx(id) < 0) return;
    @REF@ r = chunk.getReferenceTo(idx);
    if (r == null) return;
    @PR@ pr = (@PR@) st.getComponent(r, @PR@.getComponentType());
    if (pr == null) return;
    @V3I@ tg = e.getTargetBlock();
    if (tg == null) return;
    Object ext = st.getExternalData();
    if (!(ext instanceof @EST@)) return;
    @WLD@ w = ((@EST@) ext).getWorld();
    if (w == null) return;
    @PKG@.TreeSeed.onPlace0(pr.getUuid(), pr, w, w.getName(), id, tg.x(), tg.y(), tg.z());
  } catch (Throwable t) {
    if (!FAILED_ONCE) { FAILED_ONCE = true; @PKG@.TreeCfg.warn("Wide Sowing plant handler failed (logged once): " + t); }
  }
}""")
